[TFMDocumentType('applicationConfiguration')]
class TFMRequestApplicationConfigurationElement extends TFMRequestElement
{
    List configurations;

}

Method.Source:
public TFMRequestConfigurationElement parmConfiguration(TFMRequestConfigurationElement _configuration)
 {
     if(!configurations)
     {
         configurations = new List(Types::Class);
     }
     configurations.addEnd(_configuration);
     return _configuration;
 }

public Map getHandledSubRequests()
{
    Map ret;

    ret = super();

    ret.insert('configuration', classStr(TFMRequestConfigurationElement));

    return ret;
}
